<?php
namespace App\Service;
use Doctrine\DBAL\Connection;
final class Evolution {
 public function __construct(private readonly Connection $db) {}
 public function migrate(): void {
  if (!$this->db->getDatabasePlatform() instanceof \Doctrine\DBAL\Platforms\PostgreSQLPlatform) { throw new \RuntimeException('Cette évolution cible PostgreSQL.'); }
  $this->db->transactional(function(){
   $duplicates=$this->db->fetchAllAssociative("SELECT employe_id,SUBSTRING(cree_le,1,10) AS jour,COUNT(*) AS nombre FROM ticket GROUP BY employe_id,SUBSTRING(cree_le,1,10) HAVING COUNT(*)>1");
   if($duplicates){throw new \RuntimeException('Migration arrêtée sans modification : plusieurs anciens tickets créés le même jour pour un employé. Résoudre les conflits historiques avant migration : '.json_encode($duplicates,JSON_UNESCAPED_UNICODE));}
   $id='INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY';
   $defs=[
    'categorie_tarifaire'=>"id $id,nom VARCHAR(100) NOT NULL UNIQUE,prix_public INTEGER NOT NULL CHECK(prix_public>=0),prix_employe INTEGER NOT NULL CHECK(prix_employe>=0 AND prix_employe<=prix_public),actif INTEGER NOT NULL DEFAULT 1",
    'plat'=>"id $id,nom VARCHAR(150) NOT NULL,description TEXT NOT NULL DEFAULT '',categorie_id INTEGER NOT NULL REFERENCES categorie_tarifaire(id),photo VARCHAR(80),actif INTEGER NOT NULL DEFAULT 1",
    'menu_semaine'=>"id $id,jour INTEGER NOT NULL CHECK(jour BETWEEN 1 AND 7),plat_id INTEGER NOT NULL REFERENCES plat(id),UNIQUE(jour,plat_id)",
    'menu_exception'=>"date_menu VARCHAR(10) PRIMARY KEY",
    'menu_date'=>"id $id,date_menu VARCHAR(10) NOT NULL REFERENCES menu_exception(date_menu),plat_id INTEGER NOT NULL REFERENCES plat(id),UNIQUE(date_menu,plat_id)",
    'type_horaire'=>"id $id,nom VARCHAR(100) NOT NULL UNIQUE",
    'plage_horaire'=>"id $id,type_horaire_id INTEGER NOT NULL REFERENCES type_horaire(id),jour INTEGER NOT NULL CHECK(jour BETWEEN 1 AND 7),debut VARCHAR(5) NOT NULL,fin VARCHAR(5) NOT NULL",
    'affectation_horaire'=>"id $id,employe_id INTEGER NOT NULL REFERENCES employe(id),type_horaire_id INTEGER NOT NULL REFERENCES type_horaire(id),date_debut VARCHAR(10) NOT NULL,date_fin VARCHAR(10)",
    'absence'=>"id $id,employe_id INTEGER NOT NULL REFERENCES employe(id),debut VARCHAR(19) NOT NULL,fin VARCHAR(19) NOT NULL,motif VARCHAR(150) NOT NULL",
    'encaissement'=>"id $id,ticket_id INTEGER NOT NULL UNIQUE REFERENCES ticket(id),consommation_id INTEGER NOT NULL UNIQUE REFERENCES consommation(id),employe_id INTEGER NOT NULL REFERENCES employe(id),date_encaissement VARCHAR(19) NOT NULL,agent_id INTEGER NOT NULL REFERENCES utilisateur(id),montant INTEGER NOT NULL CHECK(montant>=0),prix_public INTEGER NOT NULL,subvention INTEGER NOT NULL,categorie_nom VARCHAR(100) NOT NULL,mode_paiement VARCHAR(30) NOT NULL",
    'societe'=>"id INTEGER PRIMARY KEY CHECK(id=1),nom VARCHAR(150) NOT NULL DEFAULT '',adresse TEXT NOT NULL DEFAULT '',telephone VARCHAR(50) NOT NULL DEFAULT '',email VARCHAR(180) NOT NULL DEFAULT '',identifiant_fiscal VARCHAR(100) NOT NULL DEFAULT '',logo VARCHAR(80)",
    'mobile_token'=>"id $id,utilisateur_id INTEGER NOT NULL REFERENCES utilisateur(id),token_hash VARCHAR(64) NOT NULL UNIQUE,password_fingerprint VARCHAR(64) NOT NULL,cree_le VARCHAR(19) NOT NULL,expire_le VARCHAR(19) NOT NULL",
    'evolution_schema'=>"version VARCHAR(30) PRIMARY KEY,applique_le VARCHAR(19) NOT NULL"
   ];
   foreach($defs as $table=>$cols){$this->db->executeStatement("CREATE TABLE IF NOT EXISTS $table ($cols)");}
   $this->db->executeStatement("INSERT INTO societe(id) VALUES(1) ON CONFLICT(id) DO NOTHING");
   $this->db->executeStatement('ALTER TABLE ticket ADD COLUMN IF NOT EXISTS date_emission VARCHAR(10)');
   $this->db->executeStatement('ALTER TABLE ticket ADD COLUMN IF NOT EXISTS categorie_id INTEGER REFERENCES categorie_tarifaire(id)');
   $this->db->executeStatement('ALTER TABLE ticket ADD COLUMN IF NOT EXISTS plat_indicatif_id INTEGER REFERENCES plat(id)');
   foreach(['prix_public','prix_employe','subvention'] as $c){$this->db->executeStatement("ALTER TABLE ticket ADD COLUMN IF NOT EXISTS $c INTEGER");}
   $this->db->executeStatement('ALTER TABLE ticket ADD COLUMN IF NOT EXISTS categorie_nom VARCHAR(100)');
   $this->db->executeStatement("UPDATE ticket SET date_emission=SUBSTRING(cree_le,1,10) WHERE date_emission IS NULL");
   $this->db->executeStatement('ALTER TABLE ticket ALTER COLUMN date_emission SET NOT NULL');
   $this->db->executeStatement('CREATE UNIQUE INDEX IF NOT EXISTS uq_ticket_emission ON ticket(employe_id,date_emission)');
   $oldConstraints=$this->db->fetchFirstColumn("SELECT conname FROM pg_constraint WHERE conrelid='ticket'::regclass AND contype='u' AND pg_get_constraintdef(oid)='UNIQUE (employe_id, date_repas, type_repas_id)'");
   foreach($oldConstraints as $constraint){$this->db->executeStatement('ALTER TABLE ticket DROP CONSTRAINT '.$this->db->quoteIdentifier($constraint));}
   $this->db->executeStatement('ALTER TABLE consommation ADD COLUMN IF NOT EXISTS plat_servi_id INTEGER REFERENCES plat(id)');
   $this->db->executeStatement('ALTER TABLE consommation ADD COLUMN IF NOT EXISTS service_id INTEGER REFERENCES service(id)');
   $this->db->executeStatement('ALTER TABLE consommation ADD COLUMN IF NOT EXISTS direction_id INTEGER REFERENCES direction(id)');
   $this->db->executeStatement('ALTER TABLE consommation ADD COLUMN IF NOT EXISTS plat_servi_nom VARCHAR(150)');
   $this->db->executeStatement('ALTER TABLE consommation ADD COLUMN IF NOT EXISTS categorie_nom VARCHAR(100)');
   $this->db->executeStatement('CREATE INDEX IF NOT EXISTS idx_encaissement_date ON encaissement(date_encaissement)');
   $this->db->executeStatement('CREATE INDEX IF NOT EXISTS idx_affectation_employe ON affectation_horaire(employe_id,date_debut,date_fin)');
   if(!$this->db->fetchOne("SELECT version FROM evolution_schema WHERE version='cantine-v2'")){
    foreach([['Standard 700 / 500',700,500],['Premium 1000 / 700',1000,700]] as [$nom,$public,$employee]){
     if(!$this->db->fetchOne('SELECT id FROM categorie_tarifaire WHERE nom=?',[$nom])){$this->db->insert('categorie_tarifaire',['nom'=>$nom,'prix_public'=>$public,'prix_employe'=>$employee,'actif'=>1]);}
    }
    foreach(['Normal','Quart'] as $nom){if(!$this->db->fetchOne('SELECT id FROM type_horaire WHERE nom=?',[$nom])){$this->db->insert('type_horaire',['nom'=>$nom]);}}
    // Les anciens tickets expirés restent traçables, mais ne périment plus par leur date.
    $this->db->executeStatement("UPDATE ticket SET statut='DISPONIBLE' WHERE statut='EXPIRE'");
    $this->db->executeStatement("UPDATE utilisateur SET role='ROLE_CANTINE' WHERE role IN ('ROLE_AGENT','ROLE_RESPONSABLE')");
    $this->db->insert('evolution_schema',['version'=>'cantine-v2','applique_le'=>date('Y-m-d H:i:s')]);
   }
  });
 }
}
